{noformat}view: incremental_unit_economics_rider_v2 {

  derived_table: {
    sql:
/*
    Spreadsheets coming from https://docs.google.com/spreadsheets/d/1EDOe-ZoYDqTe4zuyC6xydUkMzTAvIX8uMNkwxAVWZkg/edit#gid=2125132682
    Ticket where dashboard was developed: MARTECH-5884

    Description:
    This query takes
        daily_spend data,
        model_parameters,
        signup_to_ftr_conversion,
        avg_user_gmv
    and connects them all to one table (using daily_spend data as main key, i.e. left joining to it)
*/


    with daily_spend as (
    Select date_date,
         CASE WHEN country = 'Portugal' then 'Portugal' -- Portugal on the first place ensures it does not become 'Portugal other cities'
         WHEN city IN (Select city from ng_fivetran_google_sheets_marketing.rider_rebudgeting_cities) then city
         WHEN city NOT IN (Select city from ng_fivetran_google_sheets_marketing.rider_rebudgeting_cities) then concat(country,' other cities')
         end as city,
         country,
         replace(lower(channel_name), ' ads') as channel,
         os as platform,
         sum(metric_value) as cost
    FROM mart_models.mart_rider_ads_metrics
    where  metric_name  = 'Cost'
    and os in ('android', 'ios')
    and date_date between date('2023-01-01') and date_trunc('week', (CURRENT_DATE - INTERVAL '1' DAY)) -- dates are only defined here. Taking closest Monday as date on the right
    --and (city IN (Select city from ng_fivetran_google_sheets_marketing.rider_rebudgeting_cities) or country = 'Portugal') -- this is remainder from version before ' other cities'
    and channel_name not in ('Apple Search Brand Ads') -- ASA Brand goes as different budget and follows different decision-making.
    group by 1,2,3,4,5
    order by 1,2,3,4,5),

    model_params as (

    -- modelling
    Select city, platform, channel, DATE(modelling_date) AS from_date,
    DATE(LEAD(modelling_date, 1, date('9999-12-31')) OVER (PARTITION BY city, platform, channel ORDER BY DATE(modelling_date))) AS end_date,
    vmax_mean, lam_mean, case when has_experiment=1 then 'model+exp' else 'model' end as measurement_state
    from ng_fivetran_google_sheets_marketing.rider_mmm_curve_parameters

    Union ALL
    -- attribution
    Select city, platform, channel, DATE(modelling_date) AS from_date,
    DATE(LEAD(modelling_date, 1, date('9999-12-31')) OVER (PARTITION BY city, platform, channel ORDER BY DATE(modelling_date))) AS end_date,
    vmax_mean, lam_mean, measurement_state
    from ng_fivetran_google_sheets_marketing.rider_attribution_curve_parameters
    ),


    signup_to_ftr_conversion as (

    Select city, platfotm as platform, DATE(date) AS from_date,
    DATE(LEAD(date, 1, date('9999-12-31')) OVER (PARTITION BY city, platfotm ORDER BY DATE(date))) AS end_date,
    conversion_rate
    from ng_fivetran_google_sheets_marketing.conversion_signup_to_ftr

    ),

    avg_user_gmv as (
    Select date_date,
          CASE WHEN country = 'Portugal' then 'Portugal' -- Portugal on the first place ensures it does not become 'Portugal other cities'
          WHEN city IN (Select city from ng_fivetran_google_sheets_marketing.rider_rebudgeting_cities) then city
          WHEN city NOT IN (Select city from ng_fivetran_google_sheets_marketing.rider_rebudgeting_cities) then concat(country,' other cities')
          end as city,
          os as platform,
          sum(case when metric_name ='1Y GMV Eur' then  metric_value else 0 end) / sum(case when metric_name ='First time rides' then  metric_value else 0 end) as AVG_1Y_GMV
    FROM mart_models.mart_rider_ads_metrics
    where  metric_name  in ('1Y GMV Eur', 'First time rides')
    and os in ('android', 'ios')
    --and (city IN (Select city from ng_fivetran_google_sheets_marketing.rider_rebudgeting_cities) or country = 'Portugal') -- this is remainder from version before ' other cities'
    group by 1,2,3
    order by 1,2,3
    )

    -- collect data from all subqueries
    select ds.date_date, ds.city, ds.country, ds.channel, ds.platform, vmax_mean, lam_mean, measurement_state,
           conversion_rate, AVG_1Y_GMV, -- these two parameters only participate in table calculation, but do not show up themselves.
           cost,
           vmax_mean*cost / (lam_mean+cost) as signups,
           (conversion_rate) * (vmax_mean*cost / (lam_mean+cost)) as First_Time_Rides_projected,
           (conversion_rate*AVG_1Y_GMV) * (vmax_mean*cost / (lam_mean+cost)) as GMV_projected,
           (conversion_rate*AVG_1Y_GMV) * (vmax_mean*lam_mean) / power(lam_mean+cost, 2) as Uplift_to_cost_ratio_incremental -- Michaelis-Menten derivative

      from daily_spend ds
      left join model_params mp on ds.city = mp.city and ds.channel = mp.channel and ds.platform = mp.platform and (ds.date_date >= mp.from_date and ds.date_date < mp.end_date)
      left join signup_to_ftr_conversion conv on ds.city = conv.city and ds.platform = conv.platform and (ds.date_date >= conv.from_date and ds.date_date < conv.end_date)
      left join avg_user_gmv gmv on ds.date_date = gmv.date_date and ds.city = gmv.city and ds.platform = gmv.platform

      order by 1,2,3,4
      ;;
  }

 ############## Dates ##############
  dimension_group: date_raw {
    label: "Date"
    type: time
    timeframes: [date, week, month, quarter, year]
    sql: ${TABLE}.date_date ;;
  }

  parameter: timeframe_picker {
    default_value: "Day"
    type: string
    allowed_value: { value: "Day" }
    allowed_value: { value: "Week" }
    allowed_value: { value: "Month" }
    allowed_value: { value: "Quarter" }
  }

  dimension: dynamic_timeframe {
    label: "Dynamic Date"
    type: string
    sql: CASE
        WHEN {% parameter timeframe_picker %} = 'Day' THEN CAST(${date_raw_date} AS VARCHAR)
        WHEN {% parameter timeframe_picker %} = 'Week' THEN CAST(${date_raw_week} AS VARCHAR)
        WHEN {% parameter timeframe_picker %} = 'Month' THEN CAST(${date_raw_month} AS VARCHAR)
        WHEN {% parameter timeframe_picker %} = 'Quarter' THEN CAST(${date_raw_quarter} AS VARCHAR)
        ELSE NULL
      END ;;
  }


  ############## GEO ##############

  dimension: city {
    type: string
    sql: ${TABLE}.city ;;
  }

  # Can potentially change to country/city picker
  parameter: show_city_split {
    allowed_value: {
      label: "Yes"
      value: "Yes"
    }
    allowed_value: {
      label: "No"
      value: "No"
    }
    default_value: "Yes"
  }

  dimension: dynamic_city {
    type: string
    sql:
    CASE
    WHEN {% parameter show_city_split %} = 'Yes' THEN ${TABLE}.city
    WHEN {% parameter show_city_split %} = 'No' THEN 'All Cities'
    END ;;
  }

  dimension: country {
    type: string
    sql: ${TABLE}.country ;;
  }

############## Channel ##############
  dimension: channel {
    type: string
    sql: ${TABLE}.channel ;;
  }

  parameter: show_channel_split {
    allowed_value: {
      label: "Yes"
      value: "Yes"
    }
    allowed_value: {
      label: "No"
      value: "No"
    }
    default_value: "Yes"
  }

  dimension: dynamic_channel {
    type: string
    sql:
    CASE
    WHEN {% parameter show_channel_split %} = 'Yes' THEN ${TABLE}.channel
    WHEN {% parameter show_channel_split %} = 'No' THEN 'All Channels'
    END ;;
  }

############## Platform ##############
  dimension: platform {
    type: string
    sql: ${TABLE}.platform ;;
  }

  parameter: show_platform_split {
    allowed_value: {
      label: "Yes"
      value: "Yes"
    }
    allowed_value: {
      label: "No"
      value: "No"
    }
    default_value: "Yes"
  }

  dimension: dynamic_platform {
    type: string
    sql:
      CASE
        WHEN {% parameter show_platform_split %} = 'Yes' THEN ${TABLE}.platform
        WHEN {% parameter show_platform_split %} = 'No' THEN 'All Platforms'
      END ;;
  }

############## Model Parameters ##############
  dimension: vmax_mean {
    type: string
    sql: ${TABLE}.vmax_mean ;;
    description: "Parameter defining the curve. Is interpreted as maximal amount of signups the channel can bring."
  }

  dimension: lam_mean {
    type: string
    sql: ${TABLE}.lam_mean ;;
    description: "Parameter defining the curve. Is interpreted as cost required to reach half of maximal signups."
  }

  dimension: measurement_state {
    type: string
    sql: ${TABLE}.measurement_state ;;
    description: "Description TBD."
  }

  ############## Measures ##############
  measure: cost {
    type : sum
    sql: ${TABLE}.cost;;
    value_format: "€#,##0.0"
  }

  measure: signups {
    type : sum
    sql: ${TABLE}.signups;;
    description: "Total Signups generated by ads (derived from response curve)"
    value_format: "#,##0"
  }

  measure: conversion_rate {
    type : number
    sql: sum( ${TABLE}.First_Time_Rides_projected) / sum(${TABLE}.signups) ;;
    description: "Conversion from Signups to FTR."
    value_format: "0.00%"
  }

  measure: First_Time_Rides_projected {
    type : sum
    sql: ${TABLE}.First_Time_Rides_projected;;
    description: "Total FTRs generated by signed up users (= Signups * Conversion_rate)"
    value_format: "#,##0"
  }

  measure: AVG_1Y_GMV {
    type : number
    sql: sum(${TABLE}.GMV_projected) / sum(${TABLE}.First_Time_Rides_projected);;
    description: "Average 1Y GMV prediction per user over the period."
    value_format: "€#,##0.0"
  }

  measure: GMV_projected {
    type : sum
    sql: ${TABLE}.GMV_projected;;
    description: "Total 1Y GMV generated by signed up users (= FTR_projected * AVG_1Y_GMV)"
    value_format: "€#,##0.0"
  }

  measure: Uplift_to_cost_ratio_average {
    type : number
    sql: sum(${TABLE}.GMV_projected) / sum(${TABLE}.cost);;
    description: "GMV added by overall channel spent"
    value_format: "0.##"
  }

  measure: Uplift_to_cost_ratio_incremental {
    type : number
    sql: sum(${TABLE}.cost*${TABLE}.Uplift_to_cost_ratio_incremental) / sum(${TABLE}.cost) ;;
    description: "Incremental (marginal) GMV added by last Euro spent. Weighted by cost when aggregated."
    value_format: "0.##"
  }

}
